class Solution {
    public int minCharacters(String a,String b){
        int[] first=new int[26],second=new int[26];
        for(char letter:a.toCharArray())first[letter-'a']++;
        for(char letter:b.toCharArray())second[letter-'a']++;
        int answer=a.length()+b.length();
        for(int letter=0;letter<26;letter++)answer=Math.min(answer,a.length()+b.length()-first[letter]-second[letter]);
        int prefixFirst=0,prefixSecond=0;
        for(int boundary=0;boundary<25;boundary++){
            prefixFirst+=first[boundary];
            prefixSecond+=second[boundary];
            answer=Math.min(answer,a.length()-prefixFirst+prefixSecond);
            answer=Math.min(answer,b.length()-prefixSecond+prefixFirst);
        }
        return answer;
    }
}

